def gen(rng):
    LIMIT = 10**4

    def count_paths(n, edges):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
        memo = {}
        def f(u):
            if u == n - 1:
                return 1
            if u in memo:
                return memo[u]
            r = sum(f(v) for v in adj[u])
            memo[u] = r
            return r
        return f(0)

    def build(n, density, fixed_ends, target):
        # topological order of labels; 0 and n-1 at the two ends when fixed_ends
        mid = list(range(1, n - 1))
        rng.shuffle(mid)
        order = [0] + mid + [n - 1] if fixed_ends else rng.sample(range(n), n)
        cand = [(order[i], order[j]) for i in range(n) for j in range(i + 1, n)]
        rng.shuffle(cand)
        edges = []
        chain = [(order[i], order[i + 1]) for i in range(n - 1)] if fixed_ends else []
        for e in chain:
            edges.append(e)
        for e in cand:
            if e in edges:
                continue
            if rng.random() > density:
                continue
            edges.append(e)
            if count_paths(n, edges) > target:
                edges.pop()
        rng.shuffle(edges)
        return edges

    def fmt(n, edges):
        return f"{n} {len(edges)}\n" + '\n'.join(f"{u} {v}" for u, v in edges)

    tests = [
        fmt(2, [(0, 1)]), fmt(2, []), fmt(3, [(0, 1), (1, 2), (0, 2)]), fmt(3, [(0, 1)]),
        fmt(4, [(0, 1), (0, 2), (1, 3), (2, 3), (1, 2)]),
        fmt(4, [(3, 0), (0, 1), (1, 2)]),
        fmt(5, [(0, 4), (0, 1), (1, 4), (0, 2), (2, 1), (2, 4), (0, 3), (3, 4)]),
    ]
    for _ in range(14):
        n = rng.randint(3, 8)
        tests.append(fmt(n, build(n, rng.choice([0.3, 0.6, 0.9]), rng.random() < 0.7, 60)))
    for _ in range(3):
        n = rng.randint(10, 30)
        tests.append(fmt(n, build(n, 0.15, True, LIMIT)))
    tests.append(fmt(30, build(30, 0.2, True, LIMIT)))
    tests.append(fmt(30, build(30, 1.0, True, LIMIT)))
    tests.append(fmt(30, [(i, i + 1) for i in range(29)]))
    return tests

